module expected_max (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] m,\n    input [7:0] n,\n    output reg [31:0] result,\n    output reg done\n);\n    // State definitions\n    localparam [2:0] IDLE = 3'b000;\n    localparam [2:0] INIT = 3'b001;\n    localparam [2:0] COMPUTE_POWER = 3'b010;\n    localparam [2:0] POWER_LOOP = 3'b011;\n    localparam [2:0] ADD_SUM = 3'b100;\n    localparam [2:0] FINISH = 3'b101;\n\n    reg [2:0] state, next_state;\n    reg [7:0] i, next_i;\n    reg [7:0] j, next_j;\n    reg [31:0] power, next_power;\n    reg [31:0] sum, next_sum;\n    reg [31:0] ratio_reg;  // Registered ratio\n\n    // Fixed-point constant: 1.0 in Q16.16\n    localparam [31:0] ONE = 32'h00010000;\n\n    // Combinational multiplier\n    wire [63:0] product;\n    assign product = power * ratio_reg;  // 32x32 = 64 bit\n    wire [31:0] new_power;\n    assign new_power = product[47:16];  // Extract Q16.16\n\n    // State transition logic\n    always @(*) begin\n        next_state = state;\n        next_i = i;\n        next_j = j;\n        next_power = power;\n        next_sum = sum;\n\n        case (state)\n            IDLE: begin\n                if (start) next_state = INIT;\n            end\n\n            INIT: begin\n                next_i = 8'd1;\n                next_sum = 32'd0;\n                next_state = COMPUTE_POWER;\n            end\n\n            COMPUTE_POWER: begin\n                next_power = ONE;\n                next_j = 8'd0;\n                next_state = POWER_LOOP;\n            end\n\n            POWER_LOOP: begin\n                if (j < n) begin\n                    next_power = new_power;\n                    next_j = j + 8'd1;\n                end else begin\n                    next_state = ADD_SUM;\n                end\n            end\n\n            ADD_SUM: begin\n                next_sum = sum + power;\n                if (i < (m - 8'd1)) begin\n                    next_i = i + 8'd1;\n                    next_state = COMPUTE_POWER;\n                end else begin\n                    next_state = FINISH;\n                end\n            end\n\n            FINISH: begin\n                next_state = IDLE;\n            end\n\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            i <= 8'd0;\n            j <= 8'd0;\n            power <= 32'd0;\n            sum <= 32'd0;\n            ratio_reg <= 32'd0;\n            result <= 32'd0;\n            done <= 1'b0;\n        end else begin\n            state <= next_state;\n            i <= next_i;\n            j <= next_j;\n            power <= next_power;\n            sum <= next_sum;\n            done <= (state == FINISH) ? 1'b1 : 1'b0;\n\n            // Update ratio in COMPUTE_POWER state\n            if (state == COMPUTE_POWER) begin\n                ratio_reg <= (i * 32'd65536) / m;  // Fixed-point ratio\n            end\n\n            // Capture final result\n            if (state == FINISH) begin\n                result <= (m * 32'd65536) - sum;\n            end\n        end\n    end\nendmodule